-- Coopera Kós beta. Execute no SQL Editor de um projeto Supabase novo.
create extension if not exists pgcrypto;
do $$ begin create type public.member_role as enum ('aluno', 'mentor', 'admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.case_status as enum ('em_discussao', 'resolvido', 'oculto'); exception when duplicate_object then null; end $$;
do $$ begin create type public.case_mode as enum ('roteiro_clinico', 'texto_livre', 'modelo'); exception when duplicate_object then null; end $$;
do $$ begin create type public.attachment_kind as enum ('imagem', 'pdf', 'video'); exception when duplicate_object then null; end $$;
do $$ begin create type public.notification_kind as enum ('comentario', 'mencao', 'sintese', 'mensagem', 'moderacao'); exception when duplicate_object then null; end $$;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(full_name) between 2 and 100), initials text not null check (char_length(initials) between 1 and 4), avatar_url text, created_at timestamptz not null default now());
create table public.cohorts (id uuid primary key default gen_random_uuid(), name text not null unique, created_at timestamptz not null default now());
create table public.memberships (cohort_id uuid not null references public.cohorts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.member_role not null default 'aluno', active boolean not null default true, created_at timestamptz not null default now(), primary key (cohort_id, user_id));
create table public.clinical_cases (id uuid primary key default gen_random_uuid(), cohort_id uuid not null references public.cohorts(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete restrict, code text not null, title text not null check (char_length(title) between 5 and 160), mode public.case_mode not null, status public.case_status not null default 'em_discussao', clinical_context text check (char_length(clinical_context) <= 6000), assessment text check (char_length(assessment) <= 6000), body text check (char_length(body) <= 12000), template_name text, community_question text not null check (char_length(community_question) between 10 and 1000), tags text[] not null default '{}' check (cardinality(tags) <= 8), privacy_acknowledged_at timestamptz not null, privacy_acknowledgement_version text not null default 'beta-2026-09', resolved_at timestamptz, hidden_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (cohort_id, code));
create table public.case_attachments (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.clinical_cases(id) on delete cascade, uploader_id uuid not null references public.profiles(id) on delete restrict, storage_path text not null unique, filename text not null check (char_length(filename) between 1 and 255), kind public.attachment_kind not null, mime_type text not null, byte_size bigint not null check (byte_size > 0 and byte_size <= 52428800), created_at timestamptz not null default now());
create table public.case_comments (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.clinical_cases(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete restrict, body text not null check (char_length(body) between 1 and 4000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.comment_mentions (comment_id uuid not null references public.case_comments(id) on delete cascade, mentioned_user_id uuid not null references public.profiles(id) on delete cascade, primary key (comment_id, mentioned_user_id));
create table public.case_reactions (case_id uuid not null references public.clinical_cases(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key (case_id, user_id));
create table public.mentor_summaries (id uuid primary key default gen_random_uuid(), case_id uuid not null unique references public.clinical_cases(id) on delete cascade, mentor_id uuid not null references public.profiles(id) on delete restrict, body text not null check (char_length(body) between 20 and 8000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.direct_conversations (id uuid primary key default gen_random_uuid(), cohort_id uuid not null references public.cohorts(id) on delete cascade, created_at timestamptz not null default now());
create table public.conversation_members (conversation_id uuid not null references public.direct_conversations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, primary key (conversation_id, user_id));
create table public.direct_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.direct_conversations(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete restrict, body text not null check (char_length(body) between 1 and 4000), created_at timestamptz not null default now(), read_at timestamptz);
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, kind public.notification_kind not null, title text not null check (char_length(title) <= 180), body text check (char_length(body) <= 1000), href text, read_at timestamptz, created_at timestamptz not null default now());
create table public.content_reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete restrict, case_id uuid references public.clinical_cases(id) on delete cascade, comment_id uuid references public.case_comments(id) on delete cascade, reason text not null check (char_length(reason) between 5 and 1000), resolved_at timestamptz, resolved_by uuid references public.profiles(id), created_at timestamptz not null default now(), check (num_nonnulls(case_id, comment_id) = 1));

create index cases_feed_idx on public.clinical_cases (cohort_id, status, created_at desc);
create index comments_case_idx on public.case_comments (case_id, created_at);
create index notifications_recipient_idx on public.notifications (recipient_id, read_at, created_at desc);

create or replace function public.is_active_member(target_cohort uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.memberships where cohort_id = target_cohort and user_id = auth.uid() and active); $$;
create or replace function public.has_cohort_role(target_cohort uuid, allowed public.member_role[]) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.memberships where cohort_id = target_cohort and user_id = auth.uid() and active and role = any(allowed)); $$;
create or replace function public.shares_active_cohort(target_user uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.memberships mine join public.memberships theirs using (cohort_id) where mine.user_id = auth.uid() and mine.active and theirs.user_id = target_user and theirs.active); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ declare display_name text; begin display_name := coalesce(nullif(new.raw_user_meta_data ->> 'full_name', ''), nullif(split_part(new.email, '@', 1), ''), 'Participante'); insert into public.profiles (id, full_name, initials) values (new.id, left(display_name, 100), upper(left(regexp_replace(display_name, '[^[:alpha:]]', '', 'g'), 2))) on conflict (id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
create trigger cases_touch_updated_at before update on public.clinical_cases for each row execute procedure public.touch_updated_at();
create trigger comments_touch_updated_at before update on public.case_comments for each row execute procedure public.touch_updated_at();
create trigger summaries_touch_updated_at before update on public.mentor_summaries for each row execute procedure public.touch_updated_at();
create or replace function public.resolve_case_on_summary() returns trigger language plpgsql security definer set search_path = public as $$ begin update public.clinical_cases set status = 'resolvido', resolved_at = now() where id = new.case_id; return new; end; $$;
create trigger summary_resolves_case after insert on public.mentor_summaries for each row execute procedure public.resolve_case_on_summary();
create or replace function public.notify_case_comment() returns trigger language plpgsql security definer set search_path = public as $$ declare case_author uuid; begin select author_id into case_author from public.clinical_cases where id = new.case_id; if case_author is not null and case_author <> new.author_id then insert into public.notifications (recipient_id, kind, title, body, href) values (case_author, 'comentario', 'Novo comentário no seu caso', left(new.body, 180), '/?case=' || new.case_id); end if; return new; end; $$;
create trigger comment_creates_notification after insert on public.case_comments for each row execute procedure public.notify_case_comment();

alter table public.profiles enable row level security; alter table public.cohorts enable row level security; alter table public.memberships enable row level security; alter table public.clinical_cases enable row level security; alter table public.case_attachments enable row level security; alter table public.case_comments enable row level security; alter table public.comment_mentions enable row level security; alter table public.case_reactions enable row level security; alter table public.mentor_summaries enable row level security; alter table public.direct_conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.direct_messages enable row level security; alter table public.notifications enable row level security; alter table public.content_reports enable row level security;
create policy "profiles in same cohort" on public.profiles for select using (id = auth.uid() or public.shares_active_cohort(id));
create policy "profile owner updates" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "members see cohorts" on public.cohorts for select using (public.is_active_member(id));
create policy "admins manage cohorts" on public.cohorts for all using (public.has_cohort_role(id, array['admin']::public.member_role[])) with check (public.has_cohort_role(id, array['admin']::public.member_role[]));
create policy "members see roster" on public.memberships for select using (public.is_active_member(cohort_id));
create policy "admins manage memberships" on public.memberships for all using (public.has_cohort_role(cohort_id, array['admin']::public.member_role[])) with check (public.has_cohort_role(cohort_id, array['admin']::public.member_role[]));
create policy "members view visible cases" on public.clinical_cases for select using (public.is_active_member(cohort_id) and (status <> 'oculto' or public.has_cohort_role(cohort_id, array['admin']::public.member_role[])));
create policy "members create own cases" on public.clinical_cases for insert with check (author_id = auth.uid() and public.is_active_member(cohort_id) and status = 'em_discussao' and privacy_acknowledged_at is not null);
create policy "authors update open cases" on public.clinical_cases for update using (author_id = auth.uid() and status = 'em_discussao') with check (author_id = auth.uid() and public.is_active_member(cohort_id) and status = 'em_discussao' and privacy_acknowledged_at is not null);
create policy "admins moderate cases" on public.clinical_cases for update using (public.has_cohort_role(cohort_id, array['admin']::public.member_role[])) with check (public.has_cohort_role(cohort_id, array['admin']::public.member_role[]));
create policy "authors delete own open cases" on public.clinical_cases for delete using ((author_id = auth.uid() and status = 'em_discussao') or public.has_cohort_role(cohort_id, array['admin']::public.member_role[]));
create policy "members view attachments" on public.case_attachments for select using (exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id) and (c.status <> 'oculto' or public.has_cohort_role(c.cohort_id, array['admin']::public.member_role[]))));
create policy "authors attach to own case" on public.case_attachments for insert with check (uploader_id = auth.uid() and exists (select 1 from public.clinical_cases c where c.id = case_id and c.author_id = auth.uid() and c.status = 'em_discussao' and public.is_active_member(c.cohort_id)));
create policy "authors delete own attachment" on public.case_attachments for delete using (uploader_id = auth.uid() or exists (select 1 from public.clinical_cases c where c.id = case_id and public.has_cohort_role(c.cohort_id, array['admin']::public.member_role[])));
create policy "members view comments" on public.case_comments for select using (exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id) and (c.status <> 'oculto' or public.has_cohort_role(c.cohort_id, array['admin']::public.member_role[]))));
create policy "members add comments" on public.case_comments for insert with check (author_id = auth.uid() and exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id) and c.status <> 'oculto'));
create policy "authors edit comments" on public.case_comments for update using (author_id = auth.uid()) with check (author_id = auth.uid());
create policy "authors delete comments" on public.case_comments for delete using (author_id = auth.uid());
create policy "members view mentions" on public.comment_mentions for select using (exists (select 1 from public.case_comments cm join public.clinical_cases c on c.id = cm.case_id where cm.id = comment_id and public.is_active_member(c.cohort_id)));
create policy "authors add mentions" on public.comment_mentions for insert with check (exists (select 1 from public.case_comments cm join public.clinical_cases c on c.id = cm.case_id and cm.id = comment_id and cm.author_id = auth.uid() and public.is_active_member(c.cohort_id)) and public.shares_active_cohort(mentioned_user_id));
create policy "members view reactions" on public.case_reactions for select using (exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id)));
create policy "members react once" on public.case_reactions for insert with check (user_id = auth.uid() and exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id) and c.status <> 'oculto'));
create policy "users remove own reactions" on public.case_reactions for delete using (user_id = auth.uid());
create policy "members view summaries" on public.mentor_summaries for select using (exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id)));
create policy "mentors create summaries" on public.mentor_summaries for insert with check (mentor_id = auth.uid() and exists (select 1 from public.clinical_cases c where c.id = case_id and c.status = 'em_discussao' and public.has_cohort_role(c.cohort_id, array['mentor','admin']::public.member_role[])));
create policy "mentors update own summaries" on public.mentor_summaries for update using (mentor_id = auth.uid()) with check (mentor_id = auth.uid());
create policy "conversation members view conversation" on public.direct_conversations for select using (exists (select 1 from public.conversation_members cm where cm.conversation_id = id and cm.user_id = auth.uid()));
create policy "conversation members view roster" on public.conversation_members for select using (exists (select 1 from public.conversation_members mine where mine.conversation_id = conversation_id and mine.user_id = auth.uid()));
create policy "conversation members view messages" on public.direct_messages for select using (exists (select 1 from public.conversation_members cm where cm.conversation_id = conversation_id and cm.user_id = auth.uid()));
create policy "conversation members send messages" on public.direct_messages for insert with check (sender_id = auth.uid() and exists (select 1 from public.conversation_members cm where cm.conversation_id = conversation_id and cm.user_id = auth.uid()));
create policy "recipient notification inbox" on public.notifications for select using (recipient_id = auth.uid());
create policy "recipient marks notification read" on public.notifications for update using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());
create policy "members create reports" on public.content_reports for insert with check (reporter_id = auth.uid() and (exists (select 1 from public.clinical_cases c where c.id = case_id and public.is_active_member(c.cohort_id)) or exists (select 1 from public.case_comments cm join public.clinical_cases c on c.id = cm.case_id where cm.id = comment_id and public.is_active_member(c.cohort_id))));
create policy "admins view reports" on public.content_reports for select using (exists (select 1 from public.clinical_cases c where c.id = case_id and public.has_cohort_role(c.cohort_id, array['admin']::public.member_role[])) or exists (select 1 from public.case_comments cm join public.clinical_cases c on c.id = cm.case_id where cm.id = comment_id and public.has_cohort_role(c.cohort_id, array['admin']::public.member_role[])));

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('case-media', 'case-media', false, 52428800, array['image/jpeg','image/png','image/webp','application/pdf','video/mp4']) on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create policy "members upload cohort media" on storage.objects for insert to authenticated with check (bucket_id = 'case-media' and owner_id = auth.uid() and public.is_active_member((storage.foldername(name))[1]::uuid));
create policy "members read attached media" on storage.objects for select to authenticated using (bucket_id = 'case-media' and exists (select 1 from public.case_attachments a join public.clinical_cases c on c.id = a.case_id where a.storage_path = name and public.is_active_member(c.cohort_id) and (c.status <> 'oculto' or public.has_cohort_role(c.cohort_id, array['admin']::public.member_role[]))));
create policy "owners delete uploaded media" on storage.objects for delete to authenticated using (bucket_id = 'case-media' and owner_id = auth.uid());
